mapper.select:
SELECT id AS cardId, account_id AS accountId, product_code AS productCode
FROM benefit_card
WHERE source_channel = #{channel} AND source_ref = #{sourceRef}

mapper.update:
UPDATE benefit_hold
SET account_id = #{accountId}, card_id = #{cardId}, item_code = #{itemCode}, hold_count = #{holdCount},
    hold_amount = #{holdAmount}, cash_due = #{cashDue}, catalog_amount = #{catalogAmount}, status = #{status}
WHERE order_id = #{orderId}

UPDATE benefit_balance
SET remaining = remaining - #{amount}
WHERE card_id = #{cardId} AND item_code = #{itemCode} AND remaining >= #{amount}

UPDATE benefit_balance
SET remaining = remaining + #{amount}
WHERE card_id = #{cardId} AND item_code = #{itemCode}
